// Bluetooth lab B2 Be seen.  uv run pio run -d labs/ble-lab-b2 -e ble-lab-b2 -t upload
// The board turns from listener into broadcaster: a beacon. It packs live values (button presses,
// the chip's temperature, uptime) into its advertisement, so any phone nearby can read them without
// ever connecting. Then the same 31 bytes as an iBeacon, as an Eddystone-URL, or just a name, and
// what interval and TX power cost in battery.
//
// Wiring: the screen from lesson 03. The push button on GPIO 5 is optional (it does what BOOT does).
// The scanner is your phone: nRF Connect (Android, iPhone) or LightBlue.
//
// Views: packet · air · budget · log   (click = next view, double-click = press: the counter in the
//        packet goes up, long press = advertising on/off)
// Serial: help lists the commands. Shared code: kit/lib/ble-kit; the packets: beacon_payload.h.
#include "b2_views.h"
#include "beacon.h"
#include "ble_lab.h"
#include "server_link.h"

namespace {

b2::Beacon beacon;
b2v::AirSim airSim;
ble::ServerLink links;
uint32_t liveAt = 0;

bool on() { return beacon.settings.on; }

void drawPacket(BleLab &, FrameBuffer &fb, float) { b2v::packet(fb, beacon, on()); }
void drawAir(BleLab &, FrameBuffer &fb, float t) { b2v::air(fb, beacon, airSim, on(), t); }
void drawBudget(BleLab &, FrameBuffer &fb, float) { b2v::budget(fb, beacon); }
void drawLog(BleLab &, FrameBuffer &fb, float) { bv::log(fb); }

const BleView kViews[] = {
    {"packet", drawPacket, "press"},
    {"air", drawAir, "press"},
    {"budget", drawBudget, "press"},
    {"log", drawLog, "press"},
};

// ---- Commands ---------------------------------------------------------------------------------

void cmdMode(BleLab &lab, const String &, const String &lower) {
  static const b2::Mode modes[] = {b2::Mode::Bench, b2::Mode::IBeacon, b2::Mode::Url, b2::Mode::Name};
  for (b2::Mode m : modes)
    if (lower == b2::modeName(m)) {
      const b2::Mode before = beacon.settings.mode;
      beacon.settings.mode = m;
      if (!beacon.apply(true)) beacon.settings.mode = before, beacon.apply(true);
      return lab.showView("packet");
    }
  lab.warn("mode bench | ibeacon | url | name");
}

void cmdUrl(BleLab &lab, const String &arg, const String &) {
  if (arg.isEmpty() || arg.length() >= sizeof(beacon.settings.url)) return lab.warn("url <https://...> (short: at most 17 bytes after the scheme)");
  char before[sizeof(beacon.settings.url)];
  strlcpy(before, beacon.settings.url, sizeof(before));
  strlcpy(beacon.settings.url, arg.c_str(), sizeof(beacon.settings.url));
  beacon.settings.mode = b2::Mode::Url;
  if (!beacon.apply(true)) {
    strlcpy(beacon.settings.url, before, sizeof(beacon.settings.url));
    beacon.apply(true);
  }
}

void cmdBeacon(BleLab &lab, const String &arg, const String &) {
  const int sp = arg.indexOf(' ');
  long major = 0, minor = 0;
  if (sp < 0 || !BleLab::number(arg.substring(0, sp), 0, 65535, major) || !BleLab::number(arg.substring(sp + 1), 0, 65535, minor))
    return lab.warn("beacon <major> <minor>, each 0-65535");
  beacon.settings.beacon.major = uint16_t(major);
  beacon.settings.beacon.minor = uint16_t(minor);
  beacon.settings.mode = b2::Mode::IBeacon;
  beacon.apply(true);
}

void cmdInterval(BleLab &lab, const String &arg, const String &) {
  long ms = 0;
  const long lo = b2::minIntervalMs(beacon.settings);
  if (!BleLab::number(arg, lo, 10240, ms))
    return lab.warn("interval <ms>, %ld-10240 (%s: %ld ms is the floor)", lo, beacon.settings.connectable ? "connectable" : "not connectable", lo);
  beacon.settings.intervalMs = uint16_t(ms);
  beacon.apply(true);
}

void cmdConnectable(BleLab &lab, const String &, const String &lower) {
  if (lower != "on" && lower != "off") return lab.warn("connectable on | connectable off");
  beacon.settings.connectable = lower == "on";
  if (beacon.settings.intervalMs < b2::minIntervalMs(beacon.settings)) {
    beacon.settings.intervalMs = b2::minIntervalMs(beacon.settings);
    BLE_NOTE(Warn, "interval raised to %u ms: the floor for non-connectable", beacon.settings.intervalMs);
  }
  beacon.apply(true);
}

void cmdScanResp(BleLab &lab, const String &, const String &lower) {
  if (lower != "on" && lower != "off") return lab.warn("scanresp on | scanresp off");
  beacon.settings.scanResponse = lower == "on";
  beacon.apply(true);
}

void cmdAdv(BleLab &lab, const String &, const String &lower) {
  if (!lower.isEmpty() && lower != "on" && lower != "off") return lab.warn("adv | adv on | adv off");
  beacon.settings.on = lower.isEmpty() ? !beacon.settings.on : lower == "on";
  NimBLEDevice::getServer()->advertiseOnDisconnect(beacon.settings.on);
  links.setAdvertiseAgain(beacon.settings.on);
  if (beacon.settings.on) beacon.apply(true);
  else beacon.stop();
}

void cmdPress(BleLab &, const String &, const String &) {
  beacon.live.presses++;
  beacon.apply(false);
  BLE_NOTE(Info, "presses %u: in the next packet", beacon.live.presses);
}

void printPacket(const char *what, const b2::Packet &p) {
  Serial.printf("  %s, %u of 31 bytes:\n", what, p.n);
  const ad::Parsed ps = ad::split(p.b, p.n);
  for (int f = 0; f < ps.count; f++) {
    const ad::Field &fl = ps.fields[f];
    Serial.printf("    [%02X %02X |", fl.len + 1, fl.type);
    for (int i = 0; i < fl.len; i++) Serial.printf(" %02X", p.b[fl.offset + i]);
    Serial.printf("]  %s\n", ad::typeName(fl.type));
  }
}

void cmdBytes(BleLab &, const String &, const String &) {
  Serial.printf("%s · %s · every %u ms · TX %d dBm\n", b2::modeName(beacon.settings.mode), b2::pduName(beacon.settings), beacon.settings.intervalMs,
                NimBLEDevice::getPower());
  printPacket("advertisement", beacon.adv);
  if (beacon.rsp.n) printPacket("scan response", beacon.rsp);
  else Serial.println(beacon.settings.scanResponse ? "  scan response: empty" : "  scan response: off");
}

const BleCommand kCommands[] = {
    {"mode", "bench|ibeacon|url|name", "what the advertisement carries", cmdMode},
    {"url", "<https://...>", "the Eddystone-URL (switches to url mode)", cmdUrl},
    {"beacon", "<major> <minor>", "the iBeacon numbers (switches to ibeacon mode)", cmdBeacon},
    {"interval", "<ms>", "time between advertising events (default 100)", cmdInterval},
    {"connectable", "on|off", "may a phone connect? off = a pure beacon", cmdConnectable},
    {"scanresp", "on|off", "answer active scanners with a second packet", cmdScanResp},
    {"adv", "[on|off]", "advertise or go silent (alone: toggle; long press too)", cmdAdv},
    {"press", "", "count a press into the packet (double-click too)", cmdPress},
    {"bytes", "", "both packets, structure by structure", cmdBytes},
};

// ---- Hooks ------------------------------------------------------------------------------------

void setup(BleLab &) {
  // A server with no services of its own: in connectable mode a phone may connect, and the link
  // view's state stays right. Advertising starts again by itself when the phone hangs up.
  NimBLEServer *server = NimBLEDevice::createServer();
  server->setCallbacks(&links, false);
  beacon.live.tempCenti = int16_t(temperatureRead() * 100);
  beacon.apply(true);
}

// Once a second: fresh live values into the advertisement (the controller keeps sending the old
// bytes until we hand it new ones).
void tick(BleLab &) {
  airSim.tick(beacon.settings.intervalMs, on() && ble::link().get().radio != ble::Radio::Connected);
  if (millis() - liveAt < 1000) return;
  liveAt = millis();
  beacon.live.tempCenti = int16_t(temperatureRead() * 100);
  beacon.live.uptime = uint16_t(millis() / 1000);
  if (on()) beacon.apply(false);
}

const BleLabSpec kSpec{
    "ble-lab-b2", "B2", "Be seen", "Bench B2", kViews, sizeof(kViews) / sizeof(kViews[0]), 0,
    kCommands, sizeof(kCommands) / sizeof(kCommands[0]), setup, tick, nullptr, "adv",
};

BleLab lab(kSpec);

}  // namespace

void setup() { lab.begin(); }

void loop() { lab.loop(); }

// B2's four screens (320 x 170):
//   packet  the advertisement and the scan response as 31 cells each, one colour per AD structure,
//           decoded underneath. Bytes that changed in the last update flash white (the live values).
//   air     what the radio does with it: one advertising event every interval + advDelay, each event
//           one packet on channel 37, then 38, then 39. Drawn from the settings (the controller
//           doesn't report single events), so it's the timing, not a capture.
//   budget  what this costs a coin-cell beacon: an estimate from the interval, TX power and size
//   log     the activity log
#pragma once

#include <math.h>

#include "ad_format.h"
#include "beacon.h"
#include "ble_views.h"

namespace b2v {

using namespace bv;

inline uint16_t fieldColour(int i) {
  static const uint16_t c[] = {kBlue, pal::amber, pal::teal, kViolet, pal::coral};
  return c[i % 5];
}

// 31 cells for one packet; the length and type bytes darker than the data.
inline void cells(FrameBuffer &fb, int x, int y, const b2::Packet &p, const uint32_t *changedAt, const char *title) {
  const ad::Parsed ps = ad::split(p.b, p.n);
  const uint32_t now = millis();
  char v[24];
  snprintf(v, sizeof(v), "%s %u/31", title, p.n);
  small(fb, x, y + 1, p.n ? pal::muted : pal::dim, v);
  for (int i = 0; i < 31; i++) {
    uint16_t c = pal::dim;
    for (int f = 0; f < ps.count; f++) {
      const ad::Field &fl = ps.fields[f];
      if (i >= fl.offset - 2 && i < fl.offset + fl.len) c = i < fl.offset ? mix(fieldColour(f), pal::night, 120) : fieldColour(f);
    }
    if (changedAt && changedAt[i] && i < p.n) {
      const uint32_t age = now - changedAt[i];
      if (age < 700) c = mix(pal::ink, c, uint8_t(age * 255 / 700));
    }
    fb.fillRect(x + 76 + i * 7, y, 6, 9, c);
  }
}

// One decoded line per AD structure. Returns the next free y.
inline int decode(FrameBuffer &fb, int x, int y, const b2::Packet &p, const b2::Settings &s, int maxLines) {
  const ad::Parsed ps = ad::split(p.b, p.n);
  for (int f = 0; f < ps.count && maxLines > 0; f++, maxLines--, y += 11) {
    const ad::Field &fl = ps.fields[f];
    const uint8_t *d = p.b + fl.offset;
    char v[60];
    b2::Live live;
    if (fl.type == ad::type::kFlags) snprintf(v, sizeof(v), "Flags %02X: discoverable, LE only", d[0]);
    else if (fl.type == ad::type::kName) snprintf(v, sizeof(v), "Name \"%.*s\"", fl.len, reinterpret_cast<const char *>(d));
    else if (fl.type == ad::type::kTxPower) snprintf(v, sizeof(v), "TX power %d dBm", int8_t(d[0]));
    else if (fl.type == ad::type::kAppearance) snprintf(v, sizeof(v), "Appearance %04X (generic sensor)", ad::le16(d));
    else if (fl.type == ad::type::kUuid16All) snprintf(v, sizeof(v), "Services: %04X (Eddystone)", ad::le16(d));
    else if (fl.type == ad::type::kServiceData16) snprintf(v, sizeof(v), "Eddystone-URL %.32s", s.url);
    else if (fl.type == ad::type::kManufacturer && b2::parseBench(d, fl.len, live))
      snprintf(v, sizeof(v), "FFFF: %u presses %.2fC up %us", live.presses, live.tempCenti / 100.0f, live.uptime);
    else if (fl.type == ad::type::kManufacturer && fl.len == 25)
      snprintf(v, sizeof(v), "iBeacon major %u minor %u, %d dBm at 1 m", s.beacon.major, s.beacon.minor, s.beacon.power);
    else snprintf(v, sizeof(v), "%02X %s (%u B)", fl.type, ad::typeName(fl.type), fl.len);
    fb.fillRect(x, y + 1, 4, 5, fieldColour(f));
    small(fb, x + 8, y, pal::ink, v);
  }
  return y;
}

inline void packet(FrameBuffer &fb, const b2::Beacon &b, bool on) {
  const b2::Settings &s = b.settings;
  char v[64];
  snprintf(v, sizeof(v), "%s  %s  every %u ms", b2::modeName(s.mode), b2::pduName(s), s.intervalMs);
  bold(fb, 6, 48, on ? kBlue : pal::muted, v);
  if (!on) small(fb, 230, 36, pal::amber, "advertising off");
  cells(fb, 6, 56, b.adv, b.changedAt, "advert");
  int y = decode(fb, 6, 70, b.adv, s, 4);
  cells(fb, 6, y + 3, b.rsp, nullptr, "scan rsp");
  if (b.rsp.n) decode(fb, 6, y + 17, b.rsp, s, 2);
  else small(fb, 6, y + 17, pal::muted, s.scanResponse ? "(nothing left to put here)" : "off: a scanner that asks gets no answer");
}

// ---- air ----------------------------------------------------------------------------------------

// The advertising events, as the controller would time them from our settings.
struct AirSim {
  static constexpr int kN = 48;
  uint32_t at[kN] = {};  // event start times, ms
  uint8_t delay[kN] = {};
  int head = 0;
  uint32_t next = 0;

  void tick(uint16_t intervalMs, bool on) {
    const uint32_t now = millis();
    if (!on) {
      next = now;
      return;
    }
    while (int32_t(now - next) >= 0) {
      const uint8_t d = uint8_t(esp_random() % 11);  // advDelay: 0-10 ms, fresh every event
      at[head % kN] = next;
      delay[head % kN] = d;
      head++;
      next += intervalMs + d;
    }
  }
  uint32_t last() const { return head ? at[(head - 1) % kN] : 0; }
};

inline void air(FrameBuffer &fb, const b2::Beacon &b, const AirSim &sim, bool on, float t) {
  const b2::Settings &s = b.settings;
  const uint32_t now = millis();
  // The board, sending rings when an event fires.
  const int bx = 26, by = 66;
  fb.fillRoundRect(bx - 12, by - 9, 24, 18, 3, kPanel);
  fb.drawRoundRect(bx - 12, by - 9, 24, 18, 3, kBlue);
  small(fb, bx - 9, by - 3, pal::ink, "B2");
  const uint32_t since = now - sim.last();
  if (on && since < 400) {
    for (int i = 0; i < 3; i++) {
      const int r = 14 + int(since / 400.0f * 22) + i * 5;
      fb.drawCircle(bx, by, r, mix(kBlue, pal::night, uint8_t(std::min<uint32_t>(255, since * 255 / 400 + i * 50))));
    }
  }
  // Timeline: the last few intervals, newest on the right. Three lanes, one per channel.
  const uint32_t span = std::max<uint32_t>(120, std::min<uint32_t>(6000, s.intervalMs * 3 + 60));
  const int x0 = 70, x1 = 312, w = x1 - x0;
  static const char *const ch[] = {"37", "38", "39"};
  static const char *const mhz[] = {"2402", "2426", "2480"};
  for (int c = 0; c < 3; c++) {
    const int y = 44 + c * 16;
    fb.drawFastHLine(x0, y + 6, w, pal::dim);
    small(fb, 46, y + 2, pal::muted, ch[c]);
  }
  // Each packet takes ~0.4 ms on air + switching: at any span here they sit almost on top of each
  // other, so each lane gets a 2 px nudge and the inset below shows one event magnified.
  for (int i = 0; i < AirSim::kN && i < sim.head; i++) {
    const int k = (sim.head - 1 - i) % AirSim::kN;
    const uint32_t age = now - sim.at[k];
    if (age > span) break;
    const int x = x1 - int(age * w / span);
    for (int c = 0; c < 3; c++) fb.fillRect(x + c * 2, 44 + c * 16 + 2, 2, 9, c == 0 ? kBlue : c == 1 ? pal::teal : kViolet);
    if (i < 3) {
      char d[8];
      snprintf(d, sizeof(d), "+%u", sim.delay[k]);
      small(fb, x - 6, 92, pal::dim, d);
    }
  }
  char v[64];
  snprintf(v, sizeof(v), "last %lu ms", static_cast<unsigned long>(span));
  small(fb, x0, 102, pal::dim, v);
  small(fb, x1 - 18, 102, pal::dim, "now");

  // Inset: one event magnified. Each packet = 16 B of header and checksum + our payload, 8 us per byte
  // at 1 Mbit/s, then ~150 us for the radio to hop to the next channel.
  const int airUs = (16 + b.adv.n) * 8;
  const int iy = 116;
  small(fb, 6, iy, pal::muted, "one event:");
  const float k = 200.0f / ((airUs + 150) * 3);
  for (int c = 0; c < 3; c++) {
    const int x = 70 + int(c * (airUs + 150) * k);
    fb.fillRect(x, iy - 1, std::max(2, int(airUs * k)), 9, c == 0 ? kBlue : c == 1 ? pal::teal : kViolet);
    char lbl[16];
    snprintf(lbl, sizeof(lbl), "ch%s %s", ch[c], mhz[c]);
    small(fb, x, iy + 11, pal::muted, lbl);
  }
  snprintf(v, sizeof(v), "%d us each, %d us per event", airUs, (airUs + 150) * 3);
  small(fb, 6, iy + 24, pal::ink, v);
  const float perSec = 1000.0f / (s.intervalMs + 5);
  snprintf(v, sizeof(v), "%.1f events/s = %.0f packets/s%s", perSec, perSec * 3, on ? "" : "  (off)");
  small(fb, 6, iy + 34, on ? pal::teal : pal::muted, v);
  (void)t;
}

// ---- budget -------------------------------------------------------------------------------------

// Radio current while sending, by TX power, for a typical coin-cell beacon chip (nRF52-class, 3 V,
// DC/DC on). Above +8 dBm such chips need an external amplifier: those rows are rougher still.
inline float txMilliamps(int dbm) {
  static const int8_t p[] = {-24, -12, -8, -4, 0, 4, 8, 12, 16, 20};
  static const float ma[] = {3.2f, 4.0f, 4.3f, 4.8f, 5.3f, 7.5f, 10.0f, 14.0f, 19.0f, 26.0f};
  if (dbm <= p[0]) return ma[0];
  for (int i = 1; i < 10; i++)
    if (dbm <= p[i]) return ma[i - 1] + (ma[i] - ma[i - 1]) * (dbm - p[i - 1]) / float(p[i] - p[i - 1]);
  return ma[9];
}

struct Budget {
  float txUa, rxUa, wakeUa, sleepUa, totalUa, days;
};

// Charge per event = 3 packets at the TX current + 3 short listens (for scan requests) + waking up,
// spread over the interval, plus sleep. CR2032: 220 mAh, 80 % usable.
inline Budget estimate(uint16_t intervalMs, int dbm, int payloadBytes) {
  const float airMs = (16 + payloadBytes) * 8 / 1000.0f;
  Budget b;
  b.txUa = 3 * airMs * txMilliamps(dbm) / (intervalMs + 5) * 1000;
  b.rxUa = 3 * 0.15f * 5.0f / (intervalMs + 5) * 1000;
  b.wakeUa = 0.4f * 2.0f / (intervalMs + 5) * 1000;
  b.sleepUa = 2.0f;
  b.totalUa = b.txUa + b.rxUa + b.wakeUa + b.sleepUa;
  b.days = 220.0f * 0.8f * 1000 / b.totalUa / 24;
  return b;
}

inline void budget(FrameBuffer &fb, const b2::Beacon &b) {
  const int dbm = NimBLEDevice::getPower();
  const b2::Settings &s = b.settings;
  const Budget e = estimate(s.intervalMs, dbm, b.adv.n);
  char v[64];
  small(fb, 6, 34, pal::amber, "ESTIMATE for a coin-cell beacon chip, not this board");
  // Stacked bar of where the current goes.
  const float parts[] = {e.txUa, e.rxUa, e.wakeUa, e.sleepUa};
  static const char *const names[] = {"sending", "listening", "waking", "sleeping"};
  const uint16_t cols[] = {kBlue, pal::teal, pal::amber, pal::muted};
  int x = 6;
  for (int i = 0; i < 4; i++) {
    const int w = int(parts[i] / e.totalUa * 300);
    fb.fillRect(x, 46, w, 10, cols[i]);
    x += w;
  }
  for (int i = 0; i < 4; i++) {
    snprintf(v, sizeof(v), "%s %.1f uA", names[i], parts[i]);
    fb.fillRect(6 + i * 78, 61, 5, 5, cols[i]);
    small(fb, 14 + i * 78, 60, pal::muted, v);
  }
  snprintf(v, sizeof(v), "%.1f uA", e.totalUa);
  stat(fb, 6, 72, "average", v, pal::ink);
  if (e.days > 730) snprintf(v, sizeof(v), "%.1f years", e.days / 365);
  else snprintf(v, sizeof(v), "%.0f days", e.days);
  stat(fb, 100, 72, "on a CR2032", v, e.days > 365 ? pal::teal : e.days > 60 ? pal::amber : pal::coral);
  snprintf(v, sizeof(v), "%d dBm, %u ms", dbm, s.intervalMs);
  stat(fb, 210, 72, "settings", v);

  // Life against interval, 20 ms to 10 s (log scale), at this power; the dot = now.
  const int gx = 30, gy = 150, gw = 280, gh = 42;
  fb.drawFastHLine(gx, gy, gw, pal::dim);
  float maxDays = estimate(10000, dbm, b.adv.n).days;
  int lastX = -1, lastY = 0;
  for (int i = 0; i <= 40; i++) {
    const float ms = 20 * powf(500, i / 40.0f);
    const int px = gx + i * gw / 40;
    const int py = gy - int(estimate(uint16_t(ms), dbm, b.adv.n).days / maxDays * gh);
    if (lastX >= 0) fb.drawLine(lastX, lastY, px, py, kBlue);
    lastX = px, lastY = py;
  }
  const float pos = logf(s.intervalMs / 20.0f) / logf(500);
  const int cx = gx + int(pos * gw);
  fb.fillCircle(cx, gy - int(e.days / maxDays * gh), 3, pal::amber);
  small(fb, 4, 112, pal::dim, "life");
  small(fb, gx - 2, gy + 2, pal::dim, "20ms");
  small(fb, gx + gw - 24, gy + 2, pal::dim, "10s");
  small(fb, gx + gw / 2 - 30, gy + 2, pal::dim, "interval (log)");
  small(fb, 4, 98, pal::muted, "this board draws ~80 mA: far too much for a coin cell");
}

}  // namespace b2v

// B2's mouth: turns the settings into the two packets (beacon_payload.h) and hands them to the radio.
//
// The controller (the radio's own little processor) does the shouting by itself: once advertising
// starts, it sends the advertisement on channels 37, 38 and 39, waits the interval plus a random
// 0-10 ms ("advDelay", so two beacons never stay in lockstep), and repeats, with no CPU help.
// We only replace the data once a second so the live values stay fresh.
#pragma once

#include <NimBLEDevice.h>

#include "beacon_payload.h"
#include "ble_link.h"

namespace b2 {

struct Settings {
  Mode mode = Mode::Bench;
  char url[40] = "https://espressif.com";
  uint16_t intervalMs = 100;
  bool connectable = true;
  bool scanResponse = true;
  bool on = true;
  IBeacon beacon;
};

// What kind of advertising PDU the controller sends, from our settings.
inline const char *pduName(const Settings &s) {
  if (s.connectable) return "ADV_IND";             // connectable + scannable
  if (s.scanResponse) return "ADV_SCAN_IND";       // scannable only
  return "ADV_NONCONN_IND";                        // a pure broadcast: nobody may ask anything
}

// Bluetooth 4.x set the floor at 100 ms for non-connectable adverts, 20 ms for connectable ones.
// Bluetooth 5 allows 20 ms for every type, but beacons still keep 100 ms: older phones and the old
// rule. We keep the old floors so the lab shows the difference.
inline uint16_t minIntervalMs(const Settings &s) { return s.connectable ? 20 : 100; }

class Beacon {
 public:
  Settings settings;
  Live live;
  Packet adv, rsp;
  // millis() when each byte of the advertisement last changed: the packet view flashes them.
  uint32_t changedAt[31] = {};
  uint32_t updates = 0;

  // Rebuild the packets from settings + live values. Restart = also new parameters (interval,
  // connectable): the controller only takes those while stopped.
  bool apply(bool restart) {
    Config c;
    c.mode = settings.mode;
    c.live = live;
    c.beacon = settings.beacon;
    c.url = settings.url;
    c.txPower = int8_t(NimBLEDevice::getPower());
    c.scanResponse = settings.scanResponse;
    Packet a, r;
    const char *why = nullptr;
    if (!build(c, a, r, &why)) {
      BLE_NOTE(Bad, "%s", why);
      return false;
    }
    const uint32_t now = millis();
    for (int i = 0; i < 31; i++)
      if (i >= a.n || i >= adv.n || a.b[i] != adv.b[i]) changedAt[i] = (i < a.n) ? now : 0;
    adv = a;
    rsp = r;
    updates++;

    NimBLEAdvertising *ad = NimBLEDevice::getAdvertising();
    if (restart) {
      ad->stop();
      ad->setConnectableMode(settings.connectable ? BLE_GAP_CONN_MODE_UND : BLE_GAP_CONN_MODE_NON);
      // Discoverable = scannable when not connectable; NON + NON gives ADV_NONCONN_IND.
      ad->setDiscoverableMode(settings.connectable || settings.scanResponse ? BLE_GAP_DISC_MODE_GEN : BLE_GAP_DISC_MODE_NON);
      const uint16_t units = uint16_t(settings.intervalMs * 1000 / 625);  // 0.625 ms units
      ad->setMinInterval(units);
      ad->setMaxInterval(units);
      ad->enableScanResponse(settings.scanResponse && rsp.n > 0);
    }
    NimBLEAdvertisementData data, response;
    data.addData(adv.b, adv.n);
    ad->setAdvertisementData(data);
    if (settings.scanResponse && rsp.n > 0) {
      response.addData(rsp.b, rsp.n);
      ad->setScanResponseData(response);
    } else {
      ble_gap_adv_rsp_set_data(nullptr, 0);  // an empty answer
    }
    if (restart && settings.on) {
      if (!ad->start()) {
        BLE_NOTE(Bad, "advertising did not start");
        return false;
      }
    }
    ble::link().edit([&](ble::LinkState &s) {
      if (s.radio != ble::Radio::Connected) s.radio = settings.on ? ble::Radio::Advertising : ble::Radio::Off;
      s.advertising = settings.on;
    });
    if (restart) BLE_NOTE(Good, "%s %s every %u ms, %u+%u B", modeName(settings.mode), pduName(settings), settings.intervalMs, adv.n, rsp.n);
    return true;
  }

  void stop() {
    NimBLEDevice::getAdvertising()->stop();
    ble::link().edit([](ble::LinkState &s) {
      s.advertising = false;
      if (s.radio == ble::Radio::Advertising) s.radio = ble::Radio::Off;
    });
    BLE_NOTE(Info, "advertising off: the board is invisible");
  }

  bool advertising() { return NimBLEDevice::getAdvertising()->isAdvertising(); }
};

}  // namespace b2

// B2's packets, built byte by byte. No Arduino and no radio here, so labs/ble-lab-b2/test/host/ble_beacon_test.cpp
// checks them on the Mac.
//
// One advertisement is at most 31 bytes of AD structures ([len][type][data...], see ad_format.h).
// Each mode fills that budget differently:
//
//   bench    Flags · Name "Bench B2" · Manufacturer data FFFF + our live values     24 of 31 bytes
//   ibeacon  Flags · Manufacturer data 004C 02 15 + UUID, major, minor, power      30 of 31
//   url      Flags · 16-bit service list FEAA · Service data FEAA + Eddystone-URL   up to 31
//   name     Flags · Name · TX power                                               16 of 31
//
// The scan response (a second 31-byte packet, sent only when an active scanner asks) carries what
// did not fit: the name for ibeacon and url, the TX power and appearance for bench.
#pragma once

#include <stdint.h>
#include <string.h>

#include "ad_format.h"

namespace b2 {

enum class Mode : uint8_t { Bench, IBeacon, Url, Name };

inline const char *modeName(Mode m) {
  static const char *const names[] = {"bench", "ibeacon", "url", "name"};
  return names[static_cast<int>(m)];
}

// One packet being filled. add() refuses a structure that would not fit in 31 bytes.
struct Packet {
  uint8_t b[31] = {};
  uint8_t n = 0;

  bool add(uint8_t type, const void *data, uint8_t len) {
    if (n + 2 + len > 31) return false;
    b[n++] = uint8_t(len + 1);  // the length counts the type byte too
    b[n++] = type;
    memcpy(b + n, data, len);
    n += len;
    return true;
  }
};

// The live values the bench mode broadcasts. Everything little-endian, like the rest of BLE.
struct Live {
  uint16_t presses = 0;
  int16_t tempCenti = 0;  // °C x 100
  uint16_t uptime = 0;    // seconds, wraps after 18 hours
};

constexpr uint16_t kTestCompany = 0xFFFF;  // reserved by the Bluetooth SIG for tests: ours to use
constexpr uint8_t kBenchVersion = 1;
constexpr uint8_t kBenchLen = 9;  // company (2) + version (1) + presses (2) + temp (2) + uptime (2)

inline void benchData(const Live &l, uint8_t out[kBenchLen]) {
  out[0] = kTestCompany & 0xFF;
  out[1] = kTestCompany >> 8;
  out[2] = kBenchVersion;
  out[3] = l.presses & 0xFF;
  out[4] = l.presses >> 8;
  out[5] = uint16_t(l.tempCenti) & 0xFF;
  out[6] = uint16_t(l.tempCenti) >> 8;
  out[7] = l.uptime & 0xFF;
  out[8] = l.uptime >> 8;
}

// The reverse, as a phone app (or B1's inspect view) would read it. False if it isn't ours.
inline bool parseBench(const uint8_t *d, uint8_t len, Live &out) {
  if (len != kBenchLen || ad::le16(d) != kTestCompany || d[2] != kBenchVersion) return false;
  out.presses = ad::le16(d + 3);
  out.tempCenti = int16_t(ad::le16(d + 5));
  out.uptime = ad::le16(d + 7);
  return true;
}

struct IBeacon {
  // The proximity UUID: which "fleet" of beacons this is. Ours is the Bench service's UUID.
  uint8_t uuid[16] = {0xBA, 0x5E, 0x00, 0x00, 0xB1, 0xE5, 0x4A, 0xB1, 0x9E, 0x5C, 0xBE, 0x7C, 0xBE, 0x7C, 0xB0, 0xA7};
  uint16_t major = 1, minor = 2;  // which beacon in the fleet (a shop, a shelf)
  int8_t power = -59;             // the RSSI a phone should measure at 1 m: the distance reference
};

// Apple's layout: 4C 00 (Apple) · 02 (iBeacon) · 15 (21 bytes follow) · UUID · major · minor · power.
// Major and minor are big-endian: Apple's choice, the one exception in an otherwise little-endian packet.
inline void iBeaconData(const IBeacon &ib, uint8_t out[25]) {
  out[0] = 0x4C;
  out[1] = 0x00;
  out[2] = 0x02;
  out[3] = 0x15;
  memcpy(out + 4, ib.uuid, 16);
  out[20] = ib.major >> 8;
  out[21] = ib.major & 0xFF;
  out[22] = ib.minor >> 8;
  out[23] = ib.minor & 0xFF;
  out[24] = uint8_t(ib.power);
}

struct Config {
  Mode mode = Mode::Bench;
  const char *name = "Bench B2";
  Live live;
  IBeacon beacon;
  const char *url = "https://espressif.com";
  int8_t txPower = 9;
  bool scanResponse = true;
};

constexpr uint8_t kFlagsGeneral = 0x06;  // LE General Discoverable + BR/EDR (Classic) not supported
constexpr uint16_t kAppearanceSensor = 0x0540;

// Both packets for a configuration. False (and why) when it doesn't fit, e.g. a URL that's too long.
inline bool build(const Config &c, Packet &adv, Packet &rsp, const char **why = nullptr) {
  adv = Packet{};
  rsp = Packet{};
  const uint8_t flags = kFlagsGeneral;
  adv.add(ad::type::kFlags, &flags, 1);
  const uint8_t nameLen = uint8_t(strlen(c.name));
  switch (c.mode) {
    case Mode::Bench: {
      uint8_t d[kBenchLen];
      benchData(c.live, d);
      adv.add(ad::type::kName, c.name, nameLen);
      adv.add(ad::type::kManufacturer, d, kBenchLen);
      const uint8_t app[2] = {kAppearanceSensor & 0xFF, kAppearanceSensor >> 8};
      rsp.add(ad::type::kTxPower, &c.txPower, 1);
      rsp.add(ad::type::kAppearance, app, 2);
      break;
    }
    case Mode::IBeacon: {
      uint8_t d[25];
      iBeaconData(c.beacon, d);
      adv.add(ad::type::kManufacturer, d, 25);
      rsp.add(ad::type::kName, c.name, nameLen);
      break;
    }
    case Mode::Url: {
      // Service data = the 16-bit UUID FEAA, then the Eddystone frame.
      uint8_t d[2 + 20] = {0xAA, 0xFE};
      // Eddystone wants the power at 0 m: by convention the 1 m reference + 41 dB.
      const size_t n = ad::encodeEddystoneUrl(c.url, int8_t(c.beacon.power + 41), d + 2, 20);
      if (n == 0) {
        if (why) *why = "the URL doesn't fit: http(s)://, then at most 17 bytes (.com/ .org/ ... count as 1)";
        return false;
      }
      const uint8_t list[2] = {0xAA, 0xFE};
      adv.add(ad::type::kUuid16All, list, 2);
      if (!adv.add(ad::type::kServiceData16, d, uint8_t(n + 2))) {
        if (why) *why = "the URL doesn't fit in the 31 bytes";
        return false;
      }
      rsp.add(ad::type::kName, c.name, nameLen);
      break;
    }
    case Mode::Name:
      adv.add(ad::type::kName, c.name, nameLen);
      adv.add(ad::type::kTxPower, &c.txPower, 1);
      break;
  }
  if (!c.scanResponse) rsp = Packet{};
  return true;
}

}  // namespace b2

// The shell every Bluetooth LE lab (B1-B8) shares: the screen with its status bar, the push button
// and BOOT, the on-board LED, serial commands, and printing the activity log.
//
// A lab is a BleLabSpec: its views (each one a draw function, plus what a double-click does there),
// its serial commands, and three hooks: setup() once NimBLE is running, tick() on every loop, and
// gesture() to give the button a lab-specific meaning. Each src/ble-lab-bN/main.cpp is that list.
//
// Button or BOOT, by default: click = next view · double-click = this view's action · long press =
// the lab's long action. While a numeric comparison waits: click = yes, long press = no.
// On-board LED, unless the lab claims it: breathing blue = advertising · cyan pulse = scanning ·
// steady blue = connected · violet = encrypted · amber blink = a passkey waits · white blink = data.
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>

#include "ble_link.h"
#include "ble_views.h"
#include "button.h"
#include "display.h"
#include "pins.h"

class BleLab;

enum class Gesture : uint8_t { Click, DoubleClick, LongPress };

struct BleCommand {
  const char *name;  // the first word you type
  const char *args;  // for help, e.g. "<dBm>"
  const char *what;  // one line for help
  void (*run)(BleLab &lab, const String &arg, const String &lower);
};

struct BleView {
  const char *name;  // "radar"
  void (*draw)(BleLab &lab, FrameBuffer &fb, float t);
  const char *action;  // the command line a double-click runs on this view, or nullptr
};

struct BleLabSpec {
  const char *env;         // "ble-lab-b1"
  const char *id;          // "B1"
  const char *title;       // "Listen"
  const char *deviceName;  // what phones see: "Bench B3"
  const BleView *views;
  int viewCount;
  int startView;
  const BleCommand *commands;
  int commandCount;
  void (*setup)(BleLab &lab) = nullptr;  // after NimBLE is initialised
  void (*tick)(BleLab &lab) = nullptr;   // every loop, before drawing
  // First say on every gesture. Return true when handled, false for the default.
  bool (*gesture)(BleLab &lab, Gesture g, bool external) = nullptr;
  const char *longAction = nullptr;  // the command line a long press runs by default
};

class BleLab {
 public:
  explicit BleLab(const BleLabSpec &spec) : spec_(spec), view_(spec.startView) {}

  void begin() {
    Serial.begin(115200);
    delay(1500);
    if (!display_.begin()) {
      log_e("No memory for the frame buffer. Stopping.");
      return;
    }
    rgbLedWrite(PIN_RGB, 0, 0, 0);
    external_.begin();
    boot_.begin();
    if (!NimBLEDevice::init(spec_.deviceName)) {
      log_e("NimBLE did not start. Stopping.");
      return;
    }
    Serial.printf("\n%s: NimBLE %s up, address %s, TX power %d dBm\n", spec_.env, NimBLEDevice::getVersion(),
                  NimBLEDevice::getAddress().toString().c_str(), NimBLEDevice::getPower());
    if (spec_.setup) spec_.setup(*this);
    printHelp();
  }

  void loop() {
    FrameBuffer &fb = display_.fb();
    if (fb.pixels() == nullptr) {
      delay(1000);
      return;
    }
    pollSerial();
    handleButton(external_, true);
    handleButton(boot_, false);
    measureRssi();
    if (spec_.tick) spec_.tick(*this);
    link_ = ble::link().get();
    printActivity();
    showLed();

    const float t = millis() / 1000.0f;
    const BleView &v = spec_.views[view_];
    fb.fillScreen(pal::night);
    v.draw(*this, fb, t);
    if (passkeyShowing()) bv::passkey(fb, link_, t);
    bv::header(fb, spec_.id, v.name, view_, spec_.viewCount, link_, t);
    char hint[40];
    if (passkeyShowing() && link_.passkeyCompare) snprintf(hint, sizeof(hint), "click = yes, long = no");
    else if (v.action) snprintf(hint, sizeof(hint), "2x: %s", v.action);
    else snprintf(hint, sizeof(hint), "click: next view");
    bv::footer(fb, hint);
    display_.push();
  }

  // ---- For views and commands ------------------------------------------------------------------

  const ble::LinkState &state() const { return link_; }
  const BleLabSpec &spec() const { return spec_; }
  int view() const { return view_; }

  void setView(int v) {
    view_ = (v % spec_.viewCount + spec_.viewCount) % spec_.viewCount;
    log_i("view %d: %s", view_ + 1, spec_.views[view_].name);
  }
  void showView(const char *name) {
    for (int i = 0; i < spec_.viewCount; i++)
      if (strcmp(spec_.views[i].name, name) == 0) return setView(i);
  }

  // The lab drives the on-board LED itself (B3's LED characteristic); false hands it back.
  void claimLed(bool claimed) {
    ledClaimed_ = claimed;
    ledShown_ = 0xFFFFFFFF;
  }

  // log_w is a macro that can't be returned from a void function; this can.
  [[gnu::format(printf, 2, 3)]] void warn(const char *fmt, ...) {
    char text[120];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(text, sizeof(text), fmt, ap);
    va_end(ap);
    log_w("%s", text);
  }

  // Parse a number argument; false when it is missing, not a number or out of range.
  static bool number(const String &arg, long lo, long hi, long &out) {
    if (arg.isEmpty()) return false;
    for (size_t i = 0; i < arg.length(); i++)
      if (!isDigit(arg[i]) && !(i == 0 && arg[i] == '-')) return false;
    out = arg.toInt();
    return out >= lo && out <= hi;
  }

  void runLine(const String &raw) {
    String line = raw;
    line.trim();
    if (line.isEmpty()) return;
    const int sp = line.indexOf(' ');
    String cmd = sp < 0 ? line : line.substring(0, sp);
    String arg = sp < 0 ? String() : line.substring(sp + 1);
    cmd.toLowerCase();
    arg.trim();
    String lower = arg;
    lower.toLowerCase();
    if (cmd == "help" || cmd == "?") return printHelp();
    if (cmd == "view") {
      long n = 0;
      if (!number(arg, 1, spec_.viewCount, n)) return warn("view <1-%d>", spec_.viewCount);
      return setView(n - 1);
    }
    if (cmd == "status") return printStatus();
    if (cmd == "power") return power(arg);
    for (int i = 0; i < spec_.commandCount; i++)
      if (cmd == spec_.commands[i].name) return spec_.commands[i].run(*this, arg, lower);
    log_w("unknown command '%s' in %s (type help)", line.c_str(), spec_.env);
  }

 private:
  bool passkeyShowing() const { return link_.passkey != 0 && millis() - link_.passkeySince < 30000; }

  void printHelp() {
    Serial.printf("\nBluetooth lab %s %s  (%s)  ·  phones see \"%s\"\n", spec_.id, spec_.title, spec_.env, spec_.deviceName);
    for (int i = 0; i < spec_.commandCount; i++) {
      const BleCommand &c = spec_.commands[i];
      char usage[40];
      snprintf(usage, sizeof(usage), "%s %s", c.name, c.args);
      Serial.printf("  %-28s %s\n", usage, c.what);
    }
    Serial.printf("  %-28s %s\n", "status", "the radio, the link and its security, in detail");
    Serial.printf("  %-28s %s\n", "power <dBm>", "transmit power: -24 to 20 (default 9)");
    Serial.printf("  %-28s %s\n", "view <n>", "show screen view n");
    Serial.print("Views:");
    for (int i = 0; i < spec_.viewCount; i++)
      Serial.printf(" %d %s%s", i + 1, spec_.views[i].name, i + 1 < spec_.viewCount ? " ·" : "\n");
    Serial.println("Button (GPIO 5, optional) or BOOT: click = next view, double-click = the view's action");
  }

  void printStatus() {
    const ble::LinkState s = ble::link().get();
    Serial.printf("radio %s · this board %s · TX power %d dBm\n", ble::radioName(s.radio), NimBLEDevice::getAddress().toString().c_str(),
                  NimBLEDevice::getPower());
    if (s.radio != ble::Radio::Connected) {
      if (s.lastDisconnect >= 0) Serial.printf("last link ended: 0x%02X %s\n", s.lastDisconnect & 0xFF, ble::disconnectReason(s.lastDisconnect));
      return;
    }
    const ble::Peer &p = s.peer;
    Serial.printf("peer %s%s%s (%s) · we are the %s\n", p.addr, p.idAddr[0] ? " id " : "", p.idAddr, p.name[0] ? p.name : "no name",
                  p.central ? "peripheral" : "central");
    Serial.printf("interval %.2f ms · latency %u · timeout %u ms · MTU %u · PHY %u/%u · RSSI %d dBm\n", p.interval * 1.25f, p.latency,
                  p.timeout * 10, p.mtu, p.txPhy, p.rxPhy, p.rssi);
    Serial.printf("security: %s, %s, %s, key %u bytes\n", p.encrypted ? "encrypted" : "not encrypted",
                  p.authenticated ? "authenticated (MITM)" : "not authenticated", p.bonded ? "bonded" : "not bonded", p.keySize);
    Serial.printf("traffic: rx %lu ops / %lu B · tx %lu ops / %lu B\n", static_cast<unsigned long>(s.rxOps), static_cast<unsigned long>(s.rxBytes),
                  static_cast<unsigned long>(s.txOps), static_cast<unsigned long>(s.txBytes));
  }

  void power(const String &arg) {
    long dbm = 0;
    if (!number(arg, -24, 20, dbm)) return warn("power <dBm>, -24 to 20. Now %d dBm", NimBLEDevice::getPower());
    if (!NimBLEDevice::setPower(int8_t(dbm))) return warn("the radio refused %ld dBm", dbm);
    BLE_NOTE(Info, "TX power %d dBm", NimBLEDevice::getPower());
  }

  void pollSerial() {
    static String buffer;
    while (Serial.available()) {
      const char c = Serial.read();
      if (c == '\n' || c == '\r') {
        if (!buffer.isEmpty()) runLine(buffer);
        buffer = "";
      } else if (c == 0x08 || c == 0x7F) {
        if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
      } else if (uint8_t(c) < 0x20) {
        // Other control characters (arrow keys send escape sequences): ignore.
      } else if (buffer.length() < 120) {
        buffer += c;
      }
    }
  }

  void handleButton(Button &b, bool external) {
    Gesture g;
    switch (b.poll()) {
      case Button::Event::Click: g = Gesture::Click; break;
      case Button::Event::DoubleClick: g = Gesture::DoubleClick; break;
      case Button::Event::LongPress: g = Gesture::LongPress; break;
      default: return;
    }
    if (spec_.gesture && spec_.gesture(*this, g, external)) return;
    switch (g) {
      case Gesture::Click: setView(view_ + 1); break;
      case Gesture::DoubleClick:
        if (spec_.views[view_].action) {
          Serial.printf("> %s   (double-click)\n", spec_.views[view_].action);
          runLine(spec_.views[view_].action);
        }
        break;
      case Gesture::LongPress:
        if (spec_.longAction) {
          Serial.printf("> %s   (long press)\n", spec_.longAction);
          runLine(spec_.longAction);
        }
        break;
    }
  }

  // RSSI of a live link: the controller measures it on every connection event; we ask once a second.
  void measureRssi() {
    const ble::LinkState &s = link_;
    if (s.radio != ble::Radio::Connected || millis() - rssiAt_ < 1000) return;
    rssiAt_ = millis();
    int8_t rssi = 0;
    if (ble_gap_conn_rssi(s.peer.handle, &rssi) == 0) ble::link().edit([&](ble::LinkState &st) { st.peer.rssi = rssi; });
  }

  // New activity lines go to serial from here, in order, never from the NimBLE task.
  void printActivity() {
    ble::Activity &a = ble::activity();
    const uint32_t head = a.head();
    if (printed_ + ble::Activity::kSize < head) {
      Serial.printf("  ... %lu lines skipped\n", static_cast<unsigned long>(head - ble::Activity::kSize - printed_));
      printed_ = head - ble::Activity::kSize;
    }
    ble::ActEntry e;
    for (; printed_ < head; printed_++)
      if (a.get(printed_, e)) Serial.printf("  %s %s\n", bv::actMark(e.kind), e.text);
  }

  void showLed() {
    if (ledClaimed_) return;
    const uint32_t now = millis();
    const uint32_t traffic = link_.rxOps + link_.txOps;
    if (traffic != traffic_) traffic_ = traffic, flashUntil_ = now + 60;
    // Brightness in 12 steps, so the LED (a whole WS2812 frame per write) is only rewritten on a change.
    const float wave = 0.5f + 0.5f * sinf(now / 1000.0f * 3.1416f);
    const uint8_t breathe = uint8_t(int(wave * 11) * 8 + 6);
    uint8_t r = 0, g = 0, b = 0;
    if (passkeyShowing()) r = (now / 250) & 1 ? 120 : 0, g = r / 2;
    else if (now < flashUntil_) r = 120, g = 120, b = 120;
    else switch (link_.radio) {
      case ble::Radio::Off: break;
      case ble::Radio::Scanning: g = breathe / 2, b = breathe / 2; break;
      case ble::Radio::Advertising: b = breathe; break;
      case ble::Radio::Connecting: r = 60, g = 40; break;
      case ble::Radio::Connected:
        if (link_.peer.encrypted) r = 50, b = 90;
        else b = 90;
        break;
    }
    const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
    if (colour == ledShown_) return;
    ledShown_ = colour;
    rgbLedWrite(PIN_RGB, r, g, b);
  }

  const BleLabSpec &spec_;
  Display display_;
  Button external_{PIN_BUTTON, "button"};
  Button boot_{PIN_BOOT_BTN, "BOOT"};
  ble::LinkState link_;
  int view_;
  bool ledClaimed_ = false;
  uint32_t ledShown_ = 0xFFFFFFFF, flashUntil_ = 0, traffic_ = 0, rssiAt_ = 0, printed_ = 0;
};

// The peripheral side of a link (B3-B7): NimBLE's server callbacks, turned into ble::link() state
// and activity lines. Labs make one, hand it to the server, and override what they need.
//
// Pairing hooks are here too, because every lab after B3 meets them: a passkey to show, a number
// to compare. The passkey goes into the link state; the shell draws it over any view, and the
// button (click = yes, long press = no) or serial `yes`/`no` answers through confirm().
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>
#include <esp_random.h>

#include "ble_link.h"

namespace ble {

inline void fillPeer(Peer &p, const NimBLEConnInfo &c) {
  strlcpy(p.addr, c.getAddress().toString().c_str(), sizeof(p.addr));
  const NimBLEAddress id = c.getIdAddress();
  if (!(id == c.getAddress())) strlcpy(p.idAddr, id.toString().c_str(), sizeof(p.idAddr));
  else p.idAddr[0] = 0;
  p.addrType = c.getAddress().getType();
  p.handle = c.getConnHandle();
  p.mtu = c.getMTU();
  p.interval = c.getConnInterval();
  p.latency = c.getConnLatency();
  p.timeout = c.getConnTimeout();
  p.encrypted = c.isEncrypted();
  p.authenticated = c.isAuthenticated();
  p.bonded = c.isBonded();
  p.keySize = c.getSecKeySize();
  p.central = c.isSlave();  // we are the slave (peripheral), so the peer is the central
}

class ServerLink : public NimBLEServerCallbacks {
 public:
  // Advertising starts again by itself after a disconnect (NimBLE's advertiseOnDisconnect).
  void onConnect(NimBLEServer *, NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) {
      s.peer = Peer{};
      fillPeer(s.peer, c);
      s.radio = Radio::Connected;
      s.advertising = false;
      s.connections++;
      s.connectedAt = millis();
      s.rxOps = s.txOps = s.rxBytes = s.txBytes = 0;
    });
    BLE_NOTE(Good, "connected: %s", c.getAddress().toString().c_str());
    BLE_NOTE(Info, "interval %.2f ms, latency %u, timeout %u ms", c.getConnInterval() * 1.25f, c.getConnLatency(), c.getConnTimeout() * 10);
  }

  void onDisconnect(NimBLEServer *server, NimBLEConnInfo &c, int reason) override {
    link().edit([&](LinkState &s) {
      s.connections = s.connections ? s.connections - 1 : 0;
      s.radio = advertiseAgain_ ? Radio::Advertising : Radio::Off;
      s.advertising = advertiseAgain_;
      s.lastDisconnect = reason;
      s.passkey = 0;
    });
    BLE_NOTE(Warn, "disconnected 0x%02X: %s", reason & 0xFF, disconnectReason(reason));
    (void)server;
  }

  void onMTUChange(uint16_t mtu, NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { s.peer.mtu = mtu; });
    BLE_NOTE(Info, "MTU %u: %u bytes of data per packet", mtu, mtu - 3);
    (void)c;
  }

  void onConnParamsUpdate(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { fillPeer(s.peer, c); });
    BLE_NOTE(Info, "new params: %.2f ms, latency %u", c.getConnInterval() * 1.25f, c.getConnLatency());
  }

  void onPhyUpdate(NimBLEConnInfo &c, uint8_t tx, uint8_t rx) override {
    link().edit([&](LinkState &s) { s.peer.txPhy = tx, s.peer.rxPhy = rx; });
    BLE_NOTE(Info, "PHY now %s / %s", tx == 2 ? "2M" : tx == 3 ? "Coded" : "1M", rx == 2 ? "2M" : rx == 3 ? "Coded" : "1M");
    (void)c;
  }

  // ---- Pairing -------------------------------------------------------------------------------

  // Passkey entry, we display: six random digits, the other side types them.
  uint32_t onPassKeyDisplay() override {
    const uint32_t key = esp_random() % 1000000;
    link().edit([&](LinkState &s) { s.passkey = key ? key : 1, s.passkeyCompare = false, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "passkey %06lu: type it on the other device", static_cast<unsigned long>(key));
    return key;
  }

  // Numeric comparison: both screens show the same 6 digits; a person says yes on both.
  void onConfirmPassKey(NimBLEConnInfo &c, uint32_t pin) override {
    pendingHandle_ = c.getConnHandle();
    link().edit([&](LinkState &s) { s.passkey = pin ? pin : 1, s.passkeyCompare = true, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "compare %06lu: same on the phone? (click/yes)", static_cast<unsigned long>(pin));
  }

  void onAuthenticationComplete(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) {
      fillPeer(s.peer, c);
      s.passkey = 0;
    });
    if (c.isEncrypted())
      BLE_NOTE(Good, "secured: %s%s, key %u B", c.isAuthenticated() ? "authenticated" : "Just Works", c.isBonded() ? ", bonded" : "", c.getSecKeySize());
    else
      BLE_NOTE(Bad, "pairing failed: still plain text");
  }

  void onIdentity(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { fillPeer(s.peer, c); });
    BLE_NOTE(Info, "identity: %s", c.getIdAddress().toString().c_str());
  }

  // Answer a numeric comparison (button or serial). False when nothing is waiting.
  bool confirm(bool yes) {
    if (pendingHandle_ == 0xFFFF) return false;
    NimBLEServer *server = NimBLEDevice::getServer();
    if (server) NimBLEDevice::injectConfirmPasskey(server->getPeerInfoByHandle(pendingHandle_), yes);
    pendingHandle_ = 0xFFFF;
    link().edit([&](LinkState &s) { s.passkey = 0; });
    BLE_NOTE(Info, "you said %s", yes ? "yes, it matches" : "no");
    return true;
  }
  bool comparing() const { return pendingHandle_ != 0xFFFF; }

  void setAdvertiseAgain(bool on) { advertiseAgain_ = on; }

 private:
  uint16_t pendingHandle_ = 0xFFFF;
  bool advertiseAgain_ = true;
};

}  // namespace ble

// The advertising packet, byte by byte. No Arduino and no radio here, so kit/test/host/ble_ad_test.cpp
// checks it on the Mac.
//
// An advertisement is at most 31 bytes (legacy advertising) made of AD structures:
//
//   [len][type][data ...] [len][type][data ...] ...
//
// len counts the type byte plus the data. 02 01 06 = 2 bytes follow, type 01 (Flags), value 06
// (LE General Discoverable + BR/EDR not supported). A scan response is a second packet of 31
// bytes in the same format, sent only when a scanner asks for it (an active scan).
#pragma once

#include <math.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

namespace ad {

// ---- Splitting a packet ------------------------------------------------------------------------

struct Field {
  uint8_t type = 0;
  uint8_t offset = 0;  // where the data starts (after len and type)
  uint8_t len = 0;     // data bytes only
};

struct Parsed {
  Field fields[16];
  int count = 0;
  bool malformed = false;  // a length that runs past the end of the packet
};

inline Parsed split(const uint8_t *p, size_t n) {
  Parsed out;
  size_t i = 0;
  while (i < n && out.count < 16) {
    const uint8_t len = p[i];
    if (len == 0) break;  // padding: the rest of the packet is empty
    if (i + 1 + len > n) {
      out.malformed = true;
      break;
    }
    Field &f = out.fields[out.count++];
    f.type = p[i + 1];
    f.offset = uint8_t(i + 2);
    f.len = uint8_t(len - 1);
    i += 1 + len;
  }
  return out;
}

inline const Field *find(const Parsed &ps, uint8_t type) {
  for (int i = 0; i < ps.count; i++)
    if (ps.fields[i].type == type) return &ps.fields[i];
  return nullptr;
}

// ---- Names -----------------------------------------------------------------------------------

namespace type {
constexpr uint8_t kFlags = 0x01, kUuid16Some = 0x02, kUuid16All = 0x03, kUuid128Some = 0x06, kUuid128All = 0x07;
constexpr uint8_t kShortName = 0x08, kName = 0x09, kTxPower = 0x0A, kConnInterval = 0x12;
constexpr uint8_t kServiceData16 = 0x16, kAppearance = 0x19, kAdvInterval = 0x1A, kUri = 0x24;
constexpr uint8_t kManufacturer = 0xFF;
}  // namespace type

